INSERT INTO ontology_authoring.ontology_release
    (domain, ontology_version, description, status, release_class, validation_status, parent_ontology_version, parent_release_class, source_namespace, source_sha256, content_digest, created_by)
VALUES
    ('retail', '2026.10', 'The Claris retail product model. Eleven object types, seventeen links, twenty-one verbs, twenty evidence types and five decisions. v0.4 separates stable Configuration identity from ConfigurationVersion state from Projection into legacy systems, which is what lets one canonical version and seventy-eight physical rows both be true -- and lets the second be counted as a cost of the source systems rather than as catalogue growth.', 'draft', 'AUTHORITATIVE', NULL, NULL, NULL, 'repository:ontology/source/claris_ontology.sql', 'bf7a2f7f9e1d950f', '5877bc2971f7d4aa36615753bd55d24d8e232a85a960d1e39a740a83cf5cdc31', 'engineering:D.4G.1G.5');
