INSERT INTO ontology_authoring.ontology_notes
    (domain, ontology_version, note_id, ordinal, subject, question, blocks, owner, status)
VALUES
    ('retail', '2026.10', 'Q-001', 0, 'slp_code', 'What SLP represents, who owns its definition, and whether it is a configuration dimension, a hierarchy attribute, a pricing dimension or a reference code.', 'identity_rules IR-007; the slp_code dimension', 'UNKNOWN -- naming the owner is the ask', 'OPEN'),
    ('retail', '2026.10', 'Q-002', 1, 'identity_dimensions', 'Which dimensions create a new canonical Configuration rather than a pricing or entitlement variation.', 'IDENTITY_ASSESSMENT; the whole of phase 2', 'Product Management', 'OPEN'),
    ('retail', '2026.10', 'Q-003', 2, 'legacy_update_in_place', 'Whether changing an existing SKU always creates a new all_skus row, or only certain change classes do.', 'projection_rules PR-001, PR-002', 'Ops + IS&T', 'OPEN'),
    ('retail', '2026.10', 'Q-004', 3, 'separation_of_duties', 'The separation-of-duties rules between Ops, IS&T and Finance.', 'action_authorizations', 'IS&T', 'OPEN'),
    ('retail', '2026.10', 'Q-005', 4, 'sellable_definition', 'What Salesforce state constitutes commercially sellable.', 'The READY definition of LAUNCH_READINESS', 'Sales Operations', 'OPEN'),
    ('retail', '2026.10', 'Q-006', 5, 'evidence_capture', 'Which source-system events can be captured automatically in phase 1, and whether the workbench may record approvals.', 'Whether four required evidence types are asserted or permanently absent', 'IS&T', 'OPEN'),
    ('retail', '2026.10', 'Q-007', 6, 'join_key', 'Whether any identifier spans Marketing''s request through to the Salesforce entry, or identity genuinely starts at the material number.', 'Attaching evidence to launches that stall before minting', 'IS&T', 'OPEN');
